        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        tmp = self._lst[x]
        self._lst[x] = self._lst[y]
        self._lst[y] = tmp

    def Larger(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] > self._lst[y]

    def Smaller(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] < self._lst[y]

    def Equal(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] is self._lst[y]

    def Length(self):
        return len(self._lst)

    def count(self):
        return self._count

    def isSorted(self):
        for i in range(1, len(self._lst)):
            if self.Larger(i - 1, i):
                return False
        return True

    def isSame(self, otherLst):
        if len(self._lst) != len(otherLst):
            return False
        for i in range(len(self._lst)):
            if self._lst[i] != otherLst[i]:
                return False
        return True

def partition(A, l, r):
    i = l-1
    j = r
    while i < j:
        i+=1
        while A.Larger(r, i):
            i+=1
        j-=1
        while A.Smaller(r, j):
            j+=1
        if i < j:
            A.Swap(i, j)
    A.Swap(i, r)
    return i

def quicksort(A, l, r):
    if l < r:
        q = partition(A, l, r)
        quicksort(A, l, q-1)
        quicksort(A, q+1, r)

def listSorter(listToSort: ListToSort) -> ListToSort:
    l = 0
    r = listToSort.Length() - 1
    quicksort(listToSort, l, r)
    return listToSort
