def _isCorrect(a, b, result):
    m = len(a)
    n = len(b)
    edDis = [0] * (m + 1)
    for i in range(m + 1):
        edDis[i] = [0] * (n + 1)
    for i in range(m + 1):
        edDis[i][0] = i
    for i in range(n + 1):
        edDis[0][i] = i
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                edDis[i][j] = edDis[i - 1][j - 1]
            else:
                edDis[i][j] = 1 + min(edDis[i][j - 1], edDis[i - 1][j], edDis[i - 1][j - 1])
    return edDis[len(a)][len(b)] == result

def editDistance(a, b):
    if len(a) > len(b):
        a, b = b, a

    distances = range(len(a) + 1)
    for i2, c2 in enumerate(b):
        distances_ = [i2+1]
        for i1, c1 in enumerate(a):
            if c1 == c2:
                distances_.append(distances[i1])
            else:
                distances_.append(1 + min((distances[i1], distances[i1 + 1], distances_[-1])))
        distances = distances_
    return distances[-1]
