class ListToSort:

    def __init__(self, listInput):
        self._lst = listInput
        self._count = 0

    def Swap(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        tmp = self._lst[x]
        self._lst[x] = self._lst[y]
        self._lst[y] = tmp

    def Larger(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] > self._lst[y]

    def Smaller(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] < self._lst[y]

    def Equal(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or (y < 0):
            raise IndexError
        return self._lst[x] is self._lst[y]

    def Length(self):
        return len(self._lst)

    def count(self):
        return self._count

    def isSorted(self):
        for i in range(1, len(self._lst)):
            if self.Larger(i - 1, i):
                return False
        return True

    def isSame(self, otherLst):
        if len(self._lst) != len(otherLst):
            return False
        for i in range(len(self._lst)):
            if self._lst[i] != otherLst[i]:
                return False
        return True

def listSorter(A: ListToSort) -> ListToSort:
    for i in range(0, A.Length()-1):
        # suche kleinstes Element aus A[i..N]
        min = i
        for j in range(i, A.Length()):
            if(A.Larger(min,j)):
                min = j
        # vertausche A[i] und A[min]
        A.Swap(min, i)
    return A
